":"Marhaba Honey — 250g","cat":"Butter, Cheese & Jam","company":"Marhaba Group","brand":"Marhaba","base":"piece","kind":"standard","units":[["piece","1"],["carton","12"]]},{"name":"Marhaba Honey — 500g","cat":"Butter, Cheese & Jam","company":"Marhaba Group","brand":"Marhaba","base":"piece","kind":"standard","units":[["piece","1"],["carton","12"]]},{"name":"Al-Shifa Honey — 250g","cat":"Butter, Cheese & Jam","company":"Al-Shifa Laboratories","brand":"Al-Shifa","base":"piece","kind":"standard","units":[["piece","1"],["carton","12"]]},{"name":"Al-Shifa Honey — 500g","cat":"Butter, Cheese & Jam","company":"Al-Shifa Laboratories","brand":"Al-Shifa","base":"piece","kind":"standard","units":[["piece","1"],["carton","12"]]},{"name":"Al-Shifa Honey — 1kg","cat":"Butter, Cheese & Jam","company":"Al-Shifa Laboratories","brand":"Al-Shifa","base":"piece","kind":"standard","units":[["piece","1"],["carton","12"]]},{"name":"Young's Peanut Butter (Crunchy) — 340g","cat":"Butter, Cheese & Jam","company":"Young's Pakistan","brand":"Young's","base":"piece","kind":"standard","units":[["piece","1"],["carton","12"]]},{"name":"Young's Peanut Butter (Smooth) — 340g","cat":"Butter, Cheese & Jam","company":"Young's Pakistan","brand":"Young's","base":"piece","kind":"standard","units":[["piece","1"],["carton","12"]]}]$json$::jsonb;
  v_it    jsonb;
  v_u     jsonb;
  v_pid   uuid;
  v_cat   uuid;
  v_par   uuid;
  v_base  text;
  v_new   int := 0;
  v_skip  int := 0;
begin
  -- Categories the kirana list needs that the base tree never had.
  select id into v_par from categories where name_en = 'Personal Care' and parent_id is null limit 1;
  if v_par is not null and not exists (select 1 from categories where name_en = 'Sanitary Pads') then
    insert into categories (name_en, name_ur, parent_id, sort_order)
    values ('Sanitary Pads', 'سینیٹری پیڈ', v_par, 60);
  end if;

  select id into v_par from categories where name_en = 'Ration & Staples' and parent_id is null limit 1;
  if v_par is not null and not exists (select 1 from categories where name_en = 'Baking & Cornflour') then
    insert into categories (name_en, name_ur, parent_id, sort_order)
    values ('Baking & Cornflour', 'بیکنگ و کارن فلور', v_par, 60);
  end if;

  -- The cold cabinet gets its own heading.
  if not exists (select 1 from categories where name_en = 'Frozen & Chilled') then
    insert into categories (name_en, name_ur, parent_id, sort_order)
    values ('Frozen & Chilled', 'فروزن اشیاء', null, 115);
  end if;
  select id into v_par from categories where name_en = 'Frozen & Chilled' limit 1;
  if not exists (select 1 from categories where name_en = 'Ice Cream') then
    insert into categories (name_en, name_ur, parent_id, sort_order)
    values ('Ice Cream', 'آئس کریم', v_par, 10);
  end if;
  if not exists (select 1 from categories where name_en = 'Frozen Foods') then
    insert into categories (name_en, name_ur, parent_id, sort_order)
    values ('Frozen Foods', 'فروزن فوڈ', v_par, 20);
  end if;

  for v_it in select * from jsonb_array_elements(v_items) loop
    if exists (select 1 from products where lower(name_en) = lower(v_it->>'name')) then
      v_skip := v_skip + 1;
      continue;
    end if;

    select id into v_cat from categories where name_en = v_it->>'cat' limit 1;
    v_base := v_it->>'base';

    insert into products (name_en, name_ur, category_id, company, brand,
                          base_unit, product_kind, min_stock_level, is_active)
    values (v_it->>'name', '', v_cat, v_it->>'company', v_it->>'brand',
            v_base, v_it->>'kind', 0, false)
    returning id into v_pid;

    insert into product_costs (product_id, cost_price) values (v_pid, 0)
      on conflict (product_id) do nothing;

    for v_u in select * from jsonb_array_elements(v_it->'units') loop
      insert into product_units (product_id, unit_name, factor,
                                 retail_price, wholesale_price,
                                 retail_eligible, wholesale_eligible)
      values (v_pid, v_u->>0, (v_u->>1)::numeric, 0, 0, true, true);
    end loop;

    insert into stock (product_id, quantity_in_base_unit) values (v_pid, 0)
      on conflict (product_id) do nothing;

    v_new := v_new + 1;
  end loop;

  raise notice 'Kirana: % added, % already present.', v_new, v_skip;
end
$kir$;
